using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelinePhysicsOperations
{
    public Transform3D animated_world(RefCounted owner,string id,double time,bool simulatedParent,Settings visited)
    {
        var model=Model(owner)!;var actor=model.Call("actor_for_id",id).As<Resource>();if(actor==null||visited.ContainsKey(id)||Get(Values(actor),"position").VariantType!=Variant.Type.Vector3)return Transform3D.Identity;visited=visited.Duplicate();visited[id]=true;double at=local(owner,actor,time);var values=Values(actor);var position=_animation.sampled_value(actor,new[]{"position"},at,Get(values,"position",Vector3.Zero)).AsVector3();var rotation=_animation.sampled_value(actor,new[]{"rotation"},at,Get(values,"rotation",Vector3.Zero)).AsVector3();var scale=_animation.sampled_value(actor,new[]{"scale"},at,Get(values,"scale",Vector3.One)).AsVector3();var transform=new Transform3D(Basis.FromEuler(rotation*(Mathf.Pi/180))*Basis.FromScale(scale)*Get(values,"model_basis_residual",Basis.Identity).AsBasis(),position);var result=transform;string parentId=actor.Get("parent_id").AsString();var states=Map(owner,"states");if(parentId.Length>0){var parentWorld=animated_world(owner,parentId,time,simulatedParent,visited);if(simulatedParent&&states.TryGetValue(parentId,out var parentState)&&parentState.AsGodotDictionary()["initialized"].AsBool()){var parent=model.Call("actor_for_id",parentId).As<Resource>();double weight=parent!=null?_settings.sample(parent,local(owner,parent,time))["influence"].AsDouble():1;parentWorld=parentWorld.InterpolateWith(parentState.AsGodotDictionary()["pose"].AsTransform3D(),(float)Math.Clamp(weight,0,1));}result=parentWorld*transform;}
        foreach(var value in model.Get("actors").AsGodotArray()){var remote=value.As<Resource>();string remoteId=remote.Get("id").AsString();if(remote.Get("type_id").AsString()!="remote_transform"||remoteId==id||visited.ContainsKey(remoteId))continue;var clip=model.Call("clip_for_actor_id",remoteId).As<Resource>();if(clip==null||!_clips.contains_time(clip,time))continue;var settings=_animation.sampled_values(remote,local(owner,remote,time));if(Get(settings,"remote_actor","").AsString()!=id)continue;var source=animated_world(owner,remoteId,time,simulatedParent,visited);if(Get(settings,"set_position",true).AsBool())result.Origin=source.Origin;var basis=Get(settings,"set_rotation",true).AsBool()?source.Basis.Orthonormalized():result.Basis.Orthonormalized();result.Basis=basis*Basis.FromScale(Get(settings,"set_scale",true).AsBool()?source.Basis.Scale:result.Basis.Scale);}return result;
    }
    public Transform3D bone_world(RefCounted owner,string id,string boneName,double time)
    {
        var actor=Model(owner)!.Call("actor_for_id",id).As<Resource>();if(actor==null)return Transform3D.Identity;var result=animated_world(owner,id,time,true,new Settings());if(boneName.Length==0)return result;var bones=Get(Values(actor),"rig_bones",new GArray()).AsGodotArray();int index=-1;for(int i=0;i<bones.Count;i++)if(bones[i].AsGodotDictionary()["name"].AsString()==boneName){index=i;break;}if(index<0){warn(owner,actor.Get("display_name").AsString()+": missing attachment bone "+boneName);return result;}var physical=Get(Get(Get(Map(owner,"states"),id,new Settings()).AsGodotDictionary(),"bones",new Settings()).AsGodotDictionary(),boneName,new Settings()).AsGodotDictionary();var chain=new List<int>();var visited=new HashSet<int>();while(index>=0&&index<bones.Count&&visited.Add(index)){chain.Insert(0,index);index=bones[index].AsGodotDictionary()["parent"].AsInt32();}double at=local(owner,actor,time);foreach(int i in chain){string key=i.ToString(System.Globalization.CultureInfo.InvariantCulture);var bone=bones[i].AsGodotDictionary();var authored=Get(Get(Values(actor),"bone_poses",new Settings()).AsGodotDictionary(),key,bone).AsGodotDictionary();var position=_animation.sampled_value(actor,new[]{"bone_poses",key,"position"},at,Get(authored,"position",Vector3.Zero)).AsVector3();var rotation=_animation.sampled_value(actor,new[]{"bone_poses",key,"rotation"},at,Get(authored,"rotation",Vector3.Zero)).AsVector3();var scale=_animation.sampled_value(actor,new[]{"bone_poses",key,"scale"},at,Get(authored,"scale",Vector3.One)).AsVector3();result*=new Transform3D(Basis.FromEuler(rotation*(Mathf.Pi/180))*Basis.FromScale(scale),position);}if(physical.Count>0){var config=_settings.sample(actor,at);var bone=Get(config["bone_settings"].AsGodotDictionary(),boneName,new Settings()).AsGodotDictionary();if(Get(bone,"enabled",true).AsBool())result=result.InterpolateWith(physical["pose"].AsTransform3D(),(float)Math.Clamp(config["influence"].AsDouble()*Get(bone,"influence",1.0).AsDouble(),0,1));}return result;
    }
    public Vector3 attachment(RefCounted owner,string id,string bone,Vector3 offset,double time,Transform3D fallback){if(id.Length==0)return fallback*offset;if(Model(owner)!.Call("actor_for_id",id).AsGodotObject()==null){warn(owner,"Missing attachment actor: "+id);return fallback*offset;}return bone_world(owner,id,bone,time)*offset;}
    public Transform3D source_transform(RefCounted owner,string id,Settings config,double time){var pose=animated_world(owner,id,time,true,new Settings());string attachment=config["attachment"].AsString();if(attachment.Length>0){if(Model(owner)!.Call("actor_for_id",attachment).AsGodotObject()!=null)pose=bone_world(owner,attachment,config["attachment_bone"].AsString(),time);else warn(owner,"Missing source attachment actor: "+attachment);}pose.Origin+=pose.Basis*config["pivot"].AsVector3();return pose;}
}
